// Generated by scripts/agent_snapshot_contract.py from the JSON schema of the
// conversation answers the desktop host composes; do not edit. Regenerate
// with `node scripts/agent-snapshot-contract.mjs`; `--check` fails when it is
// stale.

import type { Effort } from "./agentCatalogContract";
import type {
  Provider,
  ProviderCondition,
  ProviderTransport,
  ThreadStatus,
  ToolCallStatus,
  ToolKind,
} from "./agentGatewayContract";

export type AgentApproval = {
  description: string | null;
  options: AgentApprovalOption[];
  reply_id: string;
  request_id: string;
  source: "agent_tool";
  /**
   * The tool the agent wants to call, as the agent names it.
   */
  tool_call: string | null;
  /**
   * One of the agent's ten tool kinds.
   */
  tool_kind: ToolKind | null;
  /**
   * The host-declared server that owns this tool, when supplied.
   */
  tool_server?: string | null;
};

export type AgentApprovalOption = {
  kind: "allow_once" | "allow_session" | "reject_once";
  /**
   * The option's own name, which may be absent: the card words an option by
   * its kind.
   */
  name: string | null;
  option_id: string;
};

/**
 * A stored document a message names, as the history echoes it.
 */
export type AgentDocumentReference = {
  media_type: string | null;
  name: string;
  sha256: string | null;
};

/**
 * A message the agent wrote.
 */
export type AgentMessageRecord = {
  /**
   * cadrumo-agent's `message_id`; null where it served none.
   */
  id: string | null;
  /**
   * The `agent` record's kind.
   */
  kind: "agent";
  reply_id: string;
  text: string;
};

/**
 * What a reply waits on: the questionnaires and the approvals it asked for and
 * nobody answered yet.
 */
export type AgentPending = {
  approvals: AgentApproval[];
  questionnaires: AgentQuestionnaire[];
};

/**
 * A message the person sent.
 */
export type AgentPersonRecord = {
  /**
   * The stored documents the message named, in the order it named them.
   */
  attachments: AgentDocumentReference[];
  /**
   * cadrumo-agent's `message_id`; null where it served none.
   */
  id: string | null;
  /**
   * The `person` record's kind.
   */
  kind: "person";
  reply_id: string;
  /**
   * When it was sent, as the agent's `timestamp`.
   */
  sent_at: string | null;
  /**
   * The skills the message loaded, by name.
   */
  skills: string[];
  text: string;
};

export type AgentQuestion = {
  id: string;
  kind: "choice" | "text";
  /**
   * A choice's options; null for a text question.
   */
  options: string[] | null;
  prompt: string;
  required: boolean;
};

export type AgentQuestionnaire = {
  questions: AgentQuestion[];
  reply_id: string;
  request_id: string;
};

/**
 * What a reply ran with, as the agent froze it when the run started.
 */
export type AgentRanWith = {
  effort: Effort | null;
  model: string | null;
  model_display_name: string | null;
  provider: Provider | null;
  provider_display_name: string | null;
  transport: ProviderTransport;
};

/**
 * The record of a reply (a run) itself.
 */
export type AgentReplyRecord = {
  /**
   * For a failed run, the agent's one line about it.
   */
  failure_reason: string | null;
  /**
   * The run's id: the reply's handle.
   */
  id: string;
  /**
   * The `reply` record's kind.
   */
  kind: "reply";
  /**
   * For a failed run, why its provider failed.
   */
  provider_condition: ProviderCondition | null;
  /**
   * Messages queued behind the run's current turn; 0 where the agent served no
   * count.
   */
  queued_messages: number;
  selection: AgentRanWith | null;
  /**
   * The run's status, from its status read or else its history.
   */
  status: ThreadStatus | null;
  usage: AgentUsage | null;
};

/**
 * One read of a conversation: its records, and what its current reply waits
 * on.
 */
export type AgentSnapshot = {
  history: AgentTurnRecord[];
  pending: AgentPending;
};

/**
 * A tool call of a reply, as its history lists it.
 */
export type AgentToolRecord = {
  /**
   * What the history says of the call, as the agent worded it and the host cut
   * it: its text, its diffs' paths and the places it touched.
   */
  details: string[];
  /**
   * cadrumo-agent's `tool_call_id`.
   */
  id: string | null;
  /**
   * The `tool` record's kind.
   */
  kind: "tool";
  reply_id: string;
  status: ToolCallStatus | null;
  /**
   * The tool's name, as the agent gives it.
   */
  title: string | null;
  tool_kind: ToolKind | null;
};

/**
 * What history lists of a conversation, oldest first: per reply, the person's
 * messages, its tool calls, the agent's messages, and last the reply's own
 * record.
 */
export type AgentTurnRecord =
  AgentPersonRecord | AgentToolRecord | AgentMessageRecord | AgentReplyRecord;

/**
 * The tokens a run's provider reported, as the agent counts them.
 */
export type AgentUsage = {
  input_tokens: number | null;
  output_tokens: number | null;
};
